#include <iostream>
#include <string>
#include <iomanip>

struct Date {
    int month{1};
    int day{1};
    int year{2000};
};

struct HealthProfile {
    std::string firstName;
    std::string lastName;
    std::string gender;
    Date dob;
    double heightInInches{0.0};
    double weightInPounds{0.0};
};

int calculateAge(const HealthProfile& hp, int currentYear) {
    return currentYear - hp.dob.year;
}

int calculateMaxHeartRate(int age) {
    return 220 - age;
}

double calculateBMI(const HealthProfile& hp) {
    if (hp.heightInInches <= 0.0) return 0.0;
    return (hp.weightInPounds * 703.0) / (hp.heightInInches * hp.heightInInches);
}

void printBMIChart() {
    std::cout << "BMI VALUES CHART:\n"
              << "  Underweight: less than 18.5\n"
              << "  Normal:      18.5 - 24.9\n"
              << "  Overweight:  25.0 - 29.9\n"
              << "  Obese:       30.0 or greater\n";
}

int main() {
    HealthProfile patient;
    int currentYear = 2024;

    if (std::cin >> patient.firstName >> patient.lastName >> patient.gender
                 >> patient.dob.month >> patient.dob.day >> patient.dob.year
                 >> patient.heightInInches >> patient.weightInPounds) {

        int age = calculateAge(patient, currentYear);
        int maxHR = calculateMaxHeartRate(age);
        double minTargetHR = maxHR * 0.50;
        double maxTargetHR = maxHR * 0.85;
        double bmi = calculateBMI(patient);

        std::cout << std::fixed << std::setprecision(1);
        std::cout << "Health Profile for " << patient.firstName << " " << patient.lastName << "\n";
        std::cout << "Gender: " << patient.gender << "\n";
        std::cout << "DOB: " << patient.dob.month << "/" << patient.dob.day << "/" << patient.dob.year << "\n";
        std::cout << "Height: " << patient.heightInInches << " in, Weight: " << patient.weightInPounds << " lbs\n";
        std::cout << "Age: " << age << " years\n";
        std::cout << "Max Heart Rate: " << maxHR << " bpm\n";
        std::cout << "Target Heart Rate: " << minTargetHR << " - " << maxTargetHR << " bpm\n";
        std::cout << "BMI: " << bmi << "\n\n";

        printBMIChart();
    }
    return 0;
}
